import {DigitalPatternWorkspace} from '../../apps/web/src/digital-pattern-workspace.js';
const id=(n:number)=>`00000000-0000-4000-8000-${String(n).padStart(12,'0')}`,wall='2026-10-27T19:36:00.000Z';
const moments=['2026-10-20T09:57:00.000Z',wall,'2026-11-01T09:57:00.000Z',null,'2026-10-20T09:57:00.000Z',wall];
const items=moments.map((asOf,index)=>({journeyId:id(10+index),sourceId:id(20+index),orderId:null,asOf,designStyleNo:`TEST-clock-${index}`,customer:'TEST',designer:'TEST',group:'sewing',node:{key:'development_sewing',instanceId:id(30+index),label:'车板',stage:'development',state:index===5?'completed':'active',round:1,occurrence:1,current:true,owner:{id:id(1),name:'TEST师傅'},operator:null,assignmentHistory:[],enteredAt:new Date(Date.parse(asOf??wall)+(index===4?3600000:-7200000)).toISOString(),actualAt:index===5?new Date(Date.parse(wall)-3600000).toISOString():null,actualQuality:'verified',expectedAt:null,expectedKind:'unset',expectedPrecision:'missing',sla:'running',completionResult:null,overdueSeconds:null,risks:[],blockers:[],records:[],inheritedFrom:null,countsInProgress:true,unavailableReason:null}} as PatternWorkspaceTask));
const result:PatternWorkspaceResult={asOf:wall,page:1,pageSize:15,total:items.length,archiveTotal:items.length,items,boardPreview:items,risks:[],owners:[],counts:Object.fromEntries(PATTERN_GROUPS.map(g=>[g.key,g.key==='sewing'?items.length:0])) as PatternWorkspaceResult['counts'],riskCounts:Object.fromEntries(PATTERN_GROUPS.map(g=>[g.key,{dueSoon:0,overdue:0}])) as PatternWorkspaceResult['riskCounts']};
